ontology.rdf_extensions:
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://example.org/qinglan/schema#SupportedUnit> owl:equivalentClass [ a owl:Restriction ;
            owl:onProperty <https://example.org/qinglan/schema#hasPlatform> ;
            owl:someValuesFrom <https://example.org/qinglan/schema#ReadyPlatform> ] .

<https://example.org/qinglan/schema#belongsTo> a owl:TransitiveProperty .

<https://example.org/qinglan/schema#commands> owl:inverseOf <https://example.org/qinglan/schema#commandedBy> .

<https://example.org/qinglan/schema#note> a owl:DatatypeProperty ;
    rdfs:range xsd:string .

<https://example.org/qinglan/schema#progress> a owl:DatatypeProperty ;
    rdfs:range xsd:integer .

<https://example.org/qinglan/schema#score> a owl:DatatypeProperty ;
    rdfs:range xsd:integer .

<https://example.org/qinglan/schema#time> a owl:DatatypeProperty ;
    rdfs:range xsd:string .

<https://example.org/qinglan/schema#ReadyPlatform> owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( <https://example.org/qinglan/schema#Platform> [ a owl:Restriction ;
                        owl:hasValue "就绪" ;
                        owl:onProperty <https://example.org/qinglan/schema#status> ] ) ] .

<https://example.org/qinglan/schema#hasPlatform> owl:inverseOf <https://example.org/qinglan/schema#belongsToUnit> .

<https://example.org/qinglan/schema#status> a owl:DatatypeProperty ;
    rdfs:range xsd:string .

ontology.rdf_document:
@prefix assess: <https://example.org/qinglan/assessment#> .
@prefix equip: <https://example.org/qinglan/equipment#> .
@prefix event: <https://example.org/qinglan/event#> .
@prefix force: <https://example.org/qinglan/force#> .
@prefix mission: <https://example.org/qinglan/mission#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix ql: <https://example.org/qinglan/schema#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix turn: <https://example.org/qinglan/turn#> .
@prefix unit: <https://example.org/qinglan/unit#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

assess:Coordination a ql:Assessment ;
    rdfs:label "体系协同度"@zh ;
    ql:derivedFrom event:E0 ;
    ql:evaluates unit:BlueTeam ;
    ql:score 82 .

assess:Readiness a ql:Assessment ;
    rdfs:label "装备就绪率"@zh ;
    ql:derivedFrom event:E0 ;
    ql:evaluates unit:BlueTeam ;
    ql:score 100 .

ql:SupportedUnit a owl:Class ;
    rdfs:label "具备就绪装备的编组〔可推导〕"@zh ;
    rdfs:subClassOf ql:Unit ;
    owl:equivalentClass [ a owl:Restriction ;
            owl:onProperty ql:hasPlatform ;
            owl:someValuesFrom ql:ReadyPlatform ] .

ql:affects a owl:ObjectProperty ;
    rdfs:label "影响对象"@zh ;
    rdfs:domain ql:Event ;
    rdfs:range ql:ExerciseObject .

ql:assignedTo a owl:ObjectProperty ;
    rdfs:label "承担任务"@zh ;
    rdfs:domain ql:Unit ;
    rdfs:range ql:Mission .

ql:belongsTo a owl:ObjectProperty,
        owl:TransitiveProperty ;
    rdfs:label "隶属于"@zh ;
    rdfs:domain ql:ExerciseObject ;
    rdfs:range ql:ExerciseObject .

ql:commands a owl:ObjectProperty ;
    rdfs:label "调度"@zh ;
    rdfs:domain ql:CommandVehicle ;
    rdfs:range ql:Unit ;
    owl:inverseOf ql:commandedBy .

ql:derivedFrom a owl:ObjectProperty ;
    rdfs:label "依据事件"@zh ;
    rdfs:domain ql:Assessment ;
    rdfs:range ql:Event .

ql:evaluates a owl:ObjectProperty ;
    rdfs:label "评估对象"@zh ;
    rdfs:domain ql:Assessment ;
    rdfs:range ql:Unit .

ql:note a owl:DatatypeProperty ;
    rdfs:label "推演说明"@zh ;
    rdfs:range xsd:string .

ql:observes a owl:ObjectProperty ;
    rdfs:label "提供观测"@zh ;
    rdfs:domain ql:ReconPlatform ;
    rdfs:range ql:Mission .

ql:occurredIn a owl:ObjectProperty ;
    rdfs:label "发生于回合"@zh ;
    rdfs:domain ql:Event ;
    rdfs:range ql:ExerciseTurn .

ql:progress a owl:DatatypeProperty ;
    rdfs:label "任务进度"@zh ;
    rdfs:range xsd:integer .

ql:score a owl:DatatypeProperty ;
    rdfs:label "评估得分"@zh ;
    rdfs:range xsd:integer .

ql:supports a owl:ObjectProperty ;
    rdfs:label "提供维护"@zh ;
    rdfs:domain ql:SupportVehicle ;
    rdfs:range ql:Unit .

ql:time a owl:DatatypeProperty ;
    rdfs:label "推演时刻"@zh ;
    rdfs:range xsd:string .

equip:C01 a ql:CommandVehicle ;
    rdfs:label "C-01 调度车"@zh ;
    ql:belongsTo unit:BlueTeam ;
    ql:commands unit:BlueTeam ;
    ql:status "就绪" .

equip:C02 a ql:CommandVehicle ;
    rdfs:label "C-02 调度车"@zh ;
    ql:belongsTo unit:RedTeam ;
    ql:commands unit:RedTeam ;
    ql:status "就绪" .

equip:G01 a ql:GroundPlatform ;
    rdfs:label "G-01 地面平台"@zh ;
    ql:belongsTo unit:BlueTeam ;
    ql:status "就绪" .

equip:G02 a ql:GroundPlatform ;
    rdfs:label "G-02 地面平台"@zh ;
    ql:belongsTo unit:BlueTeam ;
    ql:status "就绪" .

equip:L01 a ql:SupportVehicle ;
    rdfs:label "L-01 维护车"@zh ;
    ql:belongsTo unit:BlueSupport ;
    ql:status "就绪" ;
    ql:supports unit:BlueTeam .

equip:R01 a ql:ReconPlatform ;
    rdfs:label "R-01 观测平台"@zh ;
    ql:belongsTo unit:BlueTeam ;
    ql:observes mission:Observe ;
    ql:status "就绪" .

equip:R02 a ql:ReconPlatform ;
    rdfs:label "R-02 观测平台"@zh ;
    ql:belongsTo unit:BlueTeam ;
    ql:observes mission:Observe ;
    ql:status "就绪" .

equip:R03 a ql:ReconPlatform ;
    rdfs:label "R-03 观测平台"@zh ;
    ql:belongsTo unit:RedTeam ;
    ql:status "就绪" .

force:Blue a ql:Force ;
    rdfs:label "甲组"@zh .

force:Red a ql:Force ;
    rdfs:label "乙组"@zh .

mission:Coordinate a ql:Mission ;
    rdfs:label "编组协同任务"@zh ;
    ql:progress 8 ;
    ql:status "进行中" .

mission:Support a ql:Mission ;
    rdfs:label "装备维护任务"@zh ;
    ql:progress 8 ;
    ql:status "进行中" .

ql:ReadyPlatform a owl:Class ;
    rdfs:label "就绪装备〔可推导〕"@zh ;
    rdfs:subClassOf ql:Platform ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( ql:Platform [ a owl:Restriction ;
                        owl:hasValue "就绪" ;
                        owl:onProperty ql:status ] ) ] .

ql:belongsToUnit a owl:ObjectProperty ;
    rdfs:label "编配于"@zh .

ql:commandedBy a owl:ObjectProperty ;
    rdfs:label "由其调度"@zh ;
    rdfs:domain ql:Unit ;
    rdfs:range ql:CommandVehicle .

ql:hasPlatform a owl:ObjectProperty ;
    rdfs:label "编配装备"@zh ;
    rdfs:domain ql:Unit ;
    rdfs:range ql:Platform ;
    owl:inverseOf ql:belongsToUnit .

ql:status a owl:DatatypeProperty ;
    rdfs:label "运行状态"@zh ;
    rdfs:range xsd:string .

turn:T0 a ql:ExerciseTurn ;
    rdfs:label "回合 0 · 09:00"@zh ;
    ql:time "09:00" .

unit:BlueSupport a ql:Unit ;
    rdfs:label "甲组维护单元"@zh ;
    ql:assignedTo mission:Support ;
    ql:belongsTo unit:BlueTeam ;
    ql:hasPlatform equip:L01 .

event:E0 a ql:Event ;
    rdfs:label "初始编组"@zh ;
    ql:affects unit:BlueTeam ;
    ql:note "登记装备、编组关系和任务初始状态。" ;
    ql:occurredIn turn:T0 .

ql:ExerciseTurn a owl:Class ;
    rdfs:label "推演回合"@zh ;
    rdfs:subClassOf ql:ExerciseObject .

ql:Force a owl:Class ;
    rdfs:label "协作小组"@zh ;
    rdfs:subClassOf ql:ExerciseObject .

ql:GroundPlatform a owl:Class ;
    rdfs:label "地面装备"@zh ;
    rdfs:subClassOf ql:Platform .

ql:SupportVehicle a owl:Class ;
    rdfs:label "维护装备"@zh ;
    rdfs:subClassOf ql:Platform .

mission:Observe a ql:Mission ;
    rdfs:label "场域观测任务"@zh ;
    ql:progress 8 ;
    ql:status "进行中" .

unit:RedTeam a ql:Unit ;
    rdfs:label "乙组协同单元"@zh ;
    ql:belongsTo force:Red ;
    ql:hasPlatform equip:C02,
        equip:R03 .

ql:Assessment a owl:Class ;
    rdfs:label "体系评估"@zh ;
    rdfs:subClassOf ql:ExerciseObject .

ql:CommandVehicle a owl:Class ;
    rdfs:label "调度装备"@zh ;
    rdfs:subClassOf ql:Platform .

ql:Event a owl:Class ;
    rdfs:label "推演事件"@zh ;
    rdfs:subClassOf ql:ExerciseObject .

ql:ReconPlatform a owl:Class ;
    rdfs:label "观测装备"@zh ;
    rdfs:subClassOf ql:Platform .

ql:Mission a owl:Class ;
    rdfs:label "任务"@zh ;
    rdfs:subClassOf ql:ExerciseObject .

ql:Platform a owl:Class ;
    rdfs:label "装备"@zh ;
    rdfs:subClassOf ql:ExerciseObject .

ql:ExerciseObject a owl:Class ;
    rdfs:label "推演对象"@zh .

ql:Unit a owl:Class ;
    rdfs:label "协作单元"@zh ;
    rdfs:subClassOf ql:ExerciseObject .

unit:BlueTeam a ql:Unit ;
    rdfs:label "甲组协同单元"@zh ;
    ql:assignedTo mission:Coordinate,
        mission:Observe ;
    ql:belongsTo force:Blue ;
    ql:hasPlatform equip:C01,
        equip:G01,
        equip:G02,
        equip:R01,
        equip:R02 .
